using System.Text.Json;
using System.Text.Json.Serialization;

namespace ExoLauncher.Services;

internal sealed record ExoBridgeRequest(string Id, string Method, JsonElement Params, bool HasParams);

// The UI declaration is generated by ui/scripts/check-host-contract.mjs.
internal sealed record ExoUpdateResponse
{
    public bool Ok { get; init; }
    public bool? AlreadyLatest { get; init; }
    public bool? UpdateAvailable { get; init; }
    public bool? Installed { get; init; }
    public bool? ShouldExit { get; init; }
    public bool? InApp { get; init; }
    public string? Latest { get; init; }
    public string? Current { get; init; }
    public string? Message { get; init; }
    /// <summary>The offered version's What's New, from its release's whats-new.json; null when it has none or it failed validation.</summary>
    public ExoWhatsNewRelease? Upcoming { get; init; }
}

/// <summary>One release's What's New, validated by AppUpdateService.ParseWhatsNew.</summary>
internal sealed record ExoWhatsNewRelease
{
    public string Version { get; init; } = "";
    public ExoWhatsNewItem[] Items { get; init; } = [];
}

internal sealed record ExoWhatsNewItem
{
    public string Icon { get; init; } = "";
    public string Title { get; init; } = "";
    public string Detail { get; init; } = "";
}

/// <summary>
/// Stable JSON-RPC wire schema shared by WebHostBridge and its contract tests.
/// It parses one request shape and emits exactly one result/event envelope shape.
/// </summary>
internal static class ExoBridgeProtocol
{
    internal const int Version = 1;
    internal const int MaxRequestCharacters = 1024 * 1024;
    /// <summary>capture.saveImage carries a whole PNG as base64 (CaptureSaveImageAsync takes up to 90,000,000).</summary>
    internal const int MaxImageRequestCharacters = 90_000_000 + 4096;

    /// <summary>library.folderArt carries a folder's picture as base64: 15 MB (FolderArtStore.MaxBytes) and its request.</summary>
    internal const int MaxFolderArtCharacters = (int)(FolderArtStore.MaxBytes + 2) / 3 * 4;

    internal static int MaxCharactersFor(string method) =>
        method == "capture.saveImage" ? MaxImageRequestCharacters
            : method == "discord.camera" ? MaxVideoFrameCharacters // a camera keyframe, base64
            : method == "library.folderArt" ? MaxFolderArtCharacters + 4096
            : MaxRequestCharacters;

    internal const int MaxVideoFrameCharacters = 8 * 1024 * 1024;

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Converters = { new JsonStringEnumConverter(JsonNamingPolicy.CamelCase) },
    };

    /// <summary>
    /// False for anything that is not one well-formed request within its method's size.
    /// A well-formed request over its method's size still comes back with its Id and Method
    /// set, so the caller can answer it instead of leaving the page waiting.
    /// </summary>
    internal static bool TryParseRequest(string? raw, out ExoBridgeRequest request)
    {
        request = new ExoBridgeRequest(string.Empty, string.Empty, default, false);
        if (string.IsNullOrWhiteSpace(raw) || raw.Length > MaxImageRequestCharacters)
            return false;

        // A request over the usual size is read from its first words alone: only the few methods that carry a picture may be
        // that big, and a page cannot make the UI thread build a tree of tens of megabytes for any other.
        if (raw.Length > MaxRequestCharacters)
        {
            var (headId, headMethod) = ReadHead(raw);
            if (headId is null || headMethod is null) return false;
            if (raw.Length > MaxCharactersFor(headMethod))
            {
                request = new ExoBridgeRequest(headId, headMethod, default, false);
                return false;
            }
        }

        try
        {
            using var document = JsonDocument.Parse(raw);
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object ||
                !root.TryGetProperty("id", out var idElement) ||
                idElement.ValueKind != JsonValueKind.String ||
                !root.TryGetProperty("method", out var methodElement) ||
                methodElement.ValueKind != JsonValueKind.String)
                return false;

            var id = idElement.GetString();
            if (root.TryGetProperty("version", out var version) &&
                (version.ValueKind != JsonValueKind.Number || !version.TryGetInt32(out var number) || number != Version)) return false;
            var method = methodElement.GetString();
            if (string.IsNullOrWhiteSpace(id) || string.IsNullOrWhiteSpace(method) ||
                id.Length > 128 || method.Length > 128)
                return false;
            if (raw.Length > MaxCharactersFor(method))
            {
                request = new ExoBridgeRequest(id, method, default, false);
                return false;
            }

            var hasParams = root.TryGetProperty("params", out var paramsElement);
            request = new ExoBridgeRequest(
                id,
                method,
                hasParams ? paramsElement.Clone() : default,
                hasParams);
            return true;
        }
        catch (JsonException)
        {
            return false;
        }
    }

    private static readonly System.Text.RegularExpressions.Regex HeadWord =
        new(@"""(id|method)""\s*:\s*""([^""\\]{1,128})""", System.Text.RegularExpressions.RegexOptions.Compiled | System.Text.RegularExpressions.RegexOptions.CultureInvariant);

    /// <summary>The id and method named in a request's first 512 characters (the page writes them first); null for one it can't find.</summary>
    private static (string? Id, string? Method) ReadHead(string raw)
    {
        string? id = null, method = null;
        foreach (System.Text.RegularExpressions.Match match in HeadWord.Matches(raw[..Math.Min(raw.Length, 512)]))
        {
            if (match.Groups[1].Value == "id") id ??= match.Groups[2].Value;
            else method ??= match.Groups[2].Value;
        }
        return (id, method);
    }

    internal static string SerializeResponse(string id, bool ok, object? result, string? error)
    {
        var payload = new Dictionary<string, object?>
        {
            ["version"] = Version,
            ["id"] = id,
            ["ok"] = ok,
        };
        if (ok)
            payload["result"] = result;
        else
            payload["error"] = error ?? "error";
        return JsonSerializer.Serialize(payload, JsonOptions);
    }

    internal static string SerializeEvent(string name, object? data) =>
        JsonSerializer.Serialize(
            new Dictionary<string, object?>
            {
                ["version"] = Version,
                ["event"] = name,
                ["data"] = data,
            },
            JsonOptions);
}
